// THE MONEY IS COMPUTED HERE, NOT BY THE LLM.
// Offline stand-in for a parameterised SQL query against the Customer Product DB.
// In the live workflow this whole node is one Postgres node:
//   SELECT ... FROM products WHERE product_code = $1   (the qty drives the tier).

const req = $input.first().json.request;
const catalogue = $input.first().json.catalogue;

const product = catalogue.find(
  p => p.product_code.toLowerCase() === String(req.product_code).toLowerCase()
);

if (!product) {
  return [{ json: { found: false, product_code: req.product_code, qty: req.qty, customer: req.customer } }];
}

// Bulk-tender pricing: highest tier whose min_qty the order meets.
let discount = 0;
for (const t of product.bulk_tiers) {
  if (req.qty >= t.min_qty) discount = t.discount_pct;
}

const listUnit = product.list_unit_price;
const netUnit = Number((listUnit * (1 - discount / 100)).toFixed(2));
const lineTotal = Number((netUnit * req.qty).toFixed(2));
const savings = Number(((listUnit - netUnit) * req.qty).toFixed(2));
const belowMoq = req.qty < product.min_order_qty;

return [{ json: {
  found: true,
  customer: req.customer,
  product_code: product.product_code,
  description: product.description,
  uom: product.uom,
  currency: product.currency,
  qty: req.qty,
  min_order_qty: product.min_order_qty,
  below_min_order_qty: belowMoq,
  list_unit_price: listUnit,
  applied_discount_pct: discount,
  net_unit_price: netUnit,
  line_total: lineTotal,
  total_savings: savings,
  lead_time_days: product.lead_time_days
} }];
